#define RT(X) mat2(cos(X), -sin(X), sin(X), cos(X))
#define PI 3.141592

vec3 pal(vec3 a, vec3 b, vec3 c, vec3 d, float t)
{

    return a + b * cos(PI * 2.0 * (c * t + d));

}

void mainImage( out vec4 c_out, in vec2 u)
{
    vec2 rr = iResolution.xy;
    vec2 uv = (u + u - rr) / rr.y;
    float f = 1.0 / abs(sin(length(uv) + iTime));
    vec3 clr = vec3(0);
    uv *= 1.0;
    uv *= (0.62 + f * 0.5);
    vec2 uvr = uv;
    vec2 uvg = uv;
    vec2 uvb = uv;
    vec2 uvw = uv;
    uvr *= RT(iTime);
    uvg *= RT(iTime * 0.25);
    uvb *= RT(iTime * 0.5);

    vec3 a = vec3(1.9, f, 0.5);
    vec3 b = vec3(1.0, 1.0, 0.75);
    vec3 c = vec3(0.4, 0.3, 0.36);
    vec3 d = vec3(0.02, 1.78, 0.7);

    for (int i = 0; i < 7; i++)
    {

        uvr = abs(uvr) - vec2(0.35, 0.49);

        uvr *= RT(2.26);

    }


    for (int i = 0; i < 3; i++)
    {

        uvb = abs(uvb) - vec2(0.35, 0.08);

        uvb *= RT(2.22);

    }

    for (int i = 0; i < 4; i++)
    {

        uvw = abs(uvw) - vec2(0.34, 0.08);

        uvw *= RT(2.22);

    }

    clr += 0.07 / (abs(uvr.x) - 0.1);
    clr += 0.071 / (abs(uvg.x) - 0.1);
    clr += 0.0071 / (abs(uvb.x) - 0.1);
    clr += 0.0071 / (abs(uvw.x) - 0.1);

    clr = pal(a, b, c, d, clr.x + clr.y + clr.z);


    c_out = vec4(clr, 1.0);

}
